<script setup lang="ts">
usePageMeta('展馆管理','纸上生花内容与投稿管理。',true)
const username=ref(''),password=ref(''),user=ref<any>(null),busy=ref(false),error=ref(''),tab=ref('works'),records=ref<any[]>([]),edit=ref<any>(null)
const {feedback}=useFeedback(),bodyText=ref(''),sourceText=ref(''),modelText=ref(''),stepsText=ref('')
const tabNames:Record<string,string>={works:'投稿审核',articles:'知识札记',patterns:'起始纹样',tutorials:'渐进教程'}
async function fetchRecords(){busy.value=true;error.value='';try{records.value=await $fetch<any[]>(`/api/admin/${tab.value}`)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(async()=>{try{user.value=await $fetch('/api/admin/session');await fetchRecords()}catch{}})
async function signIn(){busy.value=true;error.value='';try{user.value=await writeApi('/api/admin/login',{method:'POST',body:{username:username.value,password:password.value}});password.value='';await fetchRecords()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function signOut(){try{await writeApi('/api/admin/logout',{method:'POST'});user.value=null;records.value=[];edit.value=null}catch(e){feedback(errorMessage(e),'error')}}
async function switchTab(t:string){tab.value=t;edit.value=null;await fetchRecords()}
function select(record:any){edit.value=JSON.parse(JSON.stringify(record));bodyText.value=JSON.stringify(record.body||[{heading:'',text:''}],null,2);sourceText.value=JSON.stringify(record.sources||[],null,2);modelText.value=JSON.stringify(record.model||{},null,2);stepsText.value=JSON.stringify(record.steps||[{title:'',text:'',require:'read'}],null,2)}
function newRecord(){select({title:'',summary:'',slug:'',name:'',description:'',category:'纸上故事',sort_order:records.value.length,published:false,pattern_id:null})}
async function saveContent(){busy.value=true;error.value='';try{const b={...edit.value};if(tab.value==='articles'){b.body=JSON.parse(bodyText.value);b.sources=JSON.parse(sourceText.value)}if(tab.value==='patterns'){b.model=JSON.parse(modelText.value);b.sources=JSON.parse(sourceText.value)}if(tab.value==='tutorials')b.steps=JSON.parse(stepsText.value);await writeApi(`/api/admin/${tab.value}${b.id?`/${b.id}`:''}`,{method:b.id?'PATCH':'POST',body:b});feedback('内容已保存，公开状态会立即影响前台。');edit.value=null;await fetchRecords()}catch(e){error.value=e instanceof SyntaxError?'内容格式不正确，请检查 JSON 数组。':errorMessage(e)}finally{busy.value=false}}
async function review(w:any,status:string){busy.value=true;error.value='';try{await writeApi(`/api/admin/works/${w.id}`,{method:'PATCH',body:{status,version:w.version,featured_order:Number(w.featured_order),review_note:w.review_note}});feedback(status==='published'?'作品已公开展出。':'作品已退回，创作者可在纸笺中看到意见。');await fetchRecords()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><div class="wrap page"><Breadcrumbs :items="[{label:'展馆管理'}]"/><header class="page-heading split-heading"><div><p class="eyebrow">THE CURATOR'S DESK</p><h1>把每份心意，认真安放。</h1><p>内容编辑与作品审核</p></div><button v-if="user" class="btn" @click="signOut">退出 · {{user.username}}</button></header><form v-if="!user" class="admin-login" @submit.prevent="signIn"><h2>管理员登录</h2><p>使用本地初始化时设置的管理员账号。</p><label for="admin-user">账号</label><input id="admin-user" v-model="username" autocomplete="username" required maxlength="60"/><label for="admin-password">密码</label><input id="admin-password" v-model="password" type="password" autocomplete="current-password" required maxlength="200"/><p v-if="error" role="alert" class="inline-error">{{error}}</p><button class="btn primary" :disabled="busy">{{busy?'正在核验…':'进入管理后台 ↗'}}</button></form><template v-else><div class="filter-tabs admin-tabs"><button v-for="(name,t) in tabNames" :key="t" :class="{selected:tab===t}" @click="switchTab(t)">{{name}}</button></div><p v-if="error" class="inline-error" role="alert">{{error}} <button class="text-link" @click="fetchRecords">重新读取 ↻</button></p><p v-if="busy" role="status" class="muted">正在整理展馆资料…</p><template v-if="tab==='works'"><p class="muted">通过审核才会公开。数字越小越靠前，已公开作品可调整排序或撤展。</p><div v-if="!records.length&&!busy" class="state"><h2>暂时没有待整理的作品</h2><p>访客投稿后会出现在这里。</p></div><article v-for="w in records" :key="w.id" class="review-row"><PaperArt :model="w.model" :label="w.title"/><div><p class="eyebrow">{{({pending:'待审核',published:'已公开',rejected:'已退回'} as any)[w.status]}} {{w.is_example?' / 项目原创示例':''}}</p><h2>{{w.title}}</h2><p>{{w.description}}</p><NuxtLink v-if="w.status==='published'" class="text-link" :to="`/gallery/${w.id}`">查看前台 ↗</NuxtLink></div><div class="review-controls"><label :for="`rank-${w.id}`">精选排序</label><input :id="`rank-${w.id}`" v-model="w.featured_order" type="number" min="-9999" max="9999"/><label :for="`note-${w.id}`">审核留言</label><textarea :id="`note-${w.id}`" v-model="w.review_note" maxlength="300" rows="2"/><div class="button-row"><button class="btn primary" :disabled="busy" @click="review(w,'published')">{{w.status==='published'?'保存排序':'通过并展出'}}</button><button class="btn" :disabled="busy" @click="review(w,'rejected')">{{w.status==='published'?'撤展并退回':'退回修改'}}</button></div></div></article></template><template v-else><div class="admin-toolbar"><p>编辑内容、顺序和发布状态，保存后立即生效。</p><button class="btn primary" @click="newRecord">＋ 新建{{tabNames[tab]}}</button></div><div class="admin-content-layout"><div class="admin-records"><button v-for="r in records" :key="r.id" @click="select(r)" :class="{selected:edit?.id===r.id}"><span>{{r.title||r.name}}</span><small>{{r.published?'公开':'未公开'}} / {{r.sort_order}}</small></button></div><form v-if="edit" class="content-form" @submit.prevent="saveContent"><label>{{tab==='patterns'?'纹样名称':'标题'}}<input v-if="tab==='patterns'" v-model="edit.name" maxlength="60" required/><input v-else v-model="edit.title" maxlength="100" required/></label><label v-if="tab!=='patterns'">网址标识<input v-model="edit.slug" pattern="[a-z0-9-]+" maxlength="80" required/></label><label>{{tab==='patterns'?'纹样说明':'摘要'}}<textarea v-if="tab==='patterns'" v-model="edit.description" maxlength="1000" required/><textarea v-else v-model="edit.summary" maxlength="500" required/></label><label v-if="tab==='articles'">分类<input v-model="edit.category" maxlength="30" required/></label><label>展示顺序<input v-model.number="edit.sort_order" type="number" min="-9999" max="9999" required/></label><label class="checkbox-label"><input v-model="edit.published" type="checkbox"/> 公开发布</label><label v-if="tab==='articles'">正文段落（heading、text 数组）<textarea v-model="bodyText" rows="16" spellcheck="false"/></label><label v-if="tab!=='tutorials'">来源（title、url 数组）<textarea v-model="sourceText" rows="5" spellcheck="false"/></label><label v-if="tab==='patterns'">纹样模型（可从现有纹样复制修改）<textarea v-model="modelText" rows="16" spellcheck="false"/></label><label v-if="tab==='tutorials'">教程步骤（title、text、require 数组）<textarea v-model="stepsText" rows="16" spellcheck="false"/><small>require：read、circle、triangle、drop、unfold 或 save。</small></label><p v-if="error" role="alert" class="inline-error">{{error}}</p><button class="btn primary" :disabled="busy">{{busy?'保存中…':'保存并更新前台'}}</button></form><div v-else class="state"><h2>选一份资料，开始整理。</h2></div></div></template></template></div></template>
